"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[792],{8370:function(e,t,a){var i=a(4512);a(2735);var o=a(9954);t.Z=()=>{let{email:e,socials:t,name:a}=o;return(0,i.jsxs)("footer",{id:"contact",className:"bg-ink px-4 pb-6 pt-4 text-bone tablet:px-10",children:[(0,i.jsxs)("div",{className:"grid gap-x-4 gap-y-10 pb-20 laptop:grid-cols-4 laptop:pb-[110px]",children:[(0,i.jsx)("h2",{className:"fu-title text-phi1",children:"Contact"}),(0,i.jsxs)("div",{className:"flex flex-col gap-6 laptop:col-span-2",children:[(0,i.jsx)("a",{href:"mailto:".concat(e),className:"fu-display break-all text-[32px] hover:text-signal tablet:break-normal tablet:text-[48px] laptopl:text-[64px]",children:e}),(0,i.jsx)("p",{className:"fu-meta text-bone/60",children:"Open to collaborations — based in Amsterdam."})]}),(0,i.jsx)("ul",{className:"flex flex-col gap-2 text-[15px] font-medium",children:t.map(e=>(0,i.jsx)("li",{children:(0,i.jsxs)("a",{href:e.link,target:"_blank",rel:"noreferrer",className:"hover:text-signal",children:[e.title," ↗"]})},e.id))})]}),(0,i.jsxs)("div",{className:"fu-meta flex justify-between border-t border-[#3A3B35] pt-4 text-bone/60",children:[(0,i.jsxs)("span",{children:["\xa9 ",new Date().getFullYear()," ",a]}),(0,i.jsx)("a",{href:"#top",className:"hover:text-bone",children:"Back to top ↑"})]})]})}},129:function(e,t,a){var i=a(4512),o=a(2735),s=a(9218),n=a.n(s),r=a(9954);let l=()=>{let[e,t]=(0,o.useState)(null);return(0,o.useEffect)(()=>{let e=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/Amsterdam",hour:"2-digit",minute:"2-digit"}),a=()=>t(e.format(new Date));a();let i=setInterval(a,1e4);return()=>clearInterval(i)},[]),(0,i.jsxs)("span",{children:["Amsterdam ",e||"--:--"]})};t.Z=()=>{let[e,t]=(0,o.useState)(!1),{showResume:a,email:s,name:c}=r,d=[{href:"/#work",label:"Work"},{href:"/#about",label:"About"},...a?[{href:"/resume",label:"Record"}]:[],{href:"/#contact",label:"Contact"}];return(0,i.jsxs)("header",{className:"sticky top-0 z-50 border-b border-ink bg-bone",children:[(0,i.jsxs)("div",{className:"grid h-14 grid-cols-[1fr_auto] items-center gap-x-4 px-4 text-[15px] tablet:px-10 laptop:grid-cols-4",children:[(0,i.jsx)(n(),{href:"/",className:"font-semibold",children:c}),(0,i.jsx)("span",{className:"hidden text-fieldgrey laptop:block",children:(0,i.jsx)(l,{})}),(0,i.jsx)("nav",{className:"hidden gap-6 font-medium laptop:col-span-2 laptop:flex","aria-label":"Main",children:d.map(e=>(0,i.jsx)(n(),{href:e.href,className:"hover:underline",children:e.label},e.href))}),(0,i.jsx)("button",{type:"button",className:"flex min-h-[44px] items-center px-2 font-medium laptop:hidden","aria-expanded":e,"aria-controls":"mobile-menu",onClick:()=>t(e=>!e),children:e?"Close":"Menu"})]}),e&&(0,i.jsxs)("nav",{id:"mobile-menu",className:"border-t border-ink bg-ink px-4 pb-6 text-bone laptop:hidden","aria-label":"Mobile",children:[d.map(e=>(0,i.jsx)(n(),{href:e.href,onClick:()=>t(!1),className:"fu-display block border-b border-[#3A3B35] py-4 text-[40px]",children:e.label},e.href)),(0,i.jsxs)("a",{href:"mailto:".concat(s),className:"block pt-5 text-[15px] text-signal",children:[s," ↗"]})]})]})}},9954:function(e){e.exports=JSON.parse('{"Ex":"researcher and designer","fE":"based in Amsterdam.","name":"Alice Picco","roles":["HCI specialist","Creative technologist","Designer","Digital humanist","Researcher"],"showResume":true,"email":"awlicepicco@gmail.com","socials":[{"id":"1","title":"Github","link":"https://github.com/alicepicco333"},{"id":"2","title":"LinkedIn","link":"https://www.linkedin.com/in/alice-picco-791157114/"}],"projects":[{"id":"0","title":"The Stolen Archive","description":"A customizable fictional museum showcasing looted colonial artifacts.","introText":"The Stolen Archive is a virtual exhibition of thirty objects taken during colonial wars, conquests and excavations, from the Benin Bronzes to the Parthenon Marbles. It works as a companion to a museum visit and as a museum of its own, and asks who was able to take these objects, who keeps them and who has managed to get them back.","gridImages":[{"src":"/images/projects/0-g1.jpg","caption":"Timeline tour: five eras of appropriation, from the spoils of Europe\'s wars to world wars and returns."},{"src":"/images/projects/0-g2.jpg","caption":"The collection: thirty objects from five continents, each with its origin, where it is held today and its room in the museum."},{"src":"/images/projects/0-g3.jpg","caption":"Object page for the Benin Bronzes: how they left, who claims them and who holds them."},{"src":"/images/projects/0-g4.jpg","caption":"Atlas: thirty routes from each object\'s place of origin to where it is held today."}],"middleText":"Visitors pick one of three tours (Timeline, Colonial Conquests, Geo) and choose how long and how complex the texts should be: every object has nine versions of its text for each tour, 810 in all. Each object page explains how the object left, who claims it and who holds it, with the sources for each position. An atlas traces the thirty routes on a map, and a floor plan places the objects in thirteen rooms over two floors.","highlightImage":"/images/projects/0-hl.jpg","conclusionText":"Developed for Information Modelling and Web Technologies (prof. Fabio Vitali) in the Digital Humanities and Digital Knowledge master\'s at the University of Bologna. Built in HTML, CSS and JavaScript, with inline SVG maps, 3D views of the objects, an RDF graph for every record, and dark and light themes.","imageSrc":"/images/projects/0.jpg","url":"https://alicepicco333.github.io/Looted-items-collection/","category":"Design","tags":["UX Design","Web Development"],"highlightCaption":"Home page of the exhibition, with the thirty objects along the bottom."},{"id":"1","title":"Digitalian Folktales","description":"A digital edition of Calvino\'s Fiabe Italiane, with regional language comparison.","introText":"Digitalian Folktales is a digital edition of tales from Italo Calvino\'s Fiabe italiane, read alongside the regional versions Calvino drew on.","gridImages":[{"src":"/images/projects/1-g1.jpg","caption":"Search page of the edition."}],"middleText":"The comparison view sets two versions of the same tale side by side, such as Ges\xf9 e San Pietro in Friuli and in Sicilia, each with its original dialect text and an Italian translation. For every tale the edition records where it comes from, its narrators, Calvino\'s source collection, its ATU tale type and a Propp-based reading of its outcome, animals and places, and an advanced search runs across the corpus.","highlightImage":"/images/projects/1-hl.jpg","conclusionText":"","imageSrc":"/images/projects/1.jpg","url":"https://alicepicco333.github.io/digitalian-folktales/","category":"Research","tags":["Digital Edition"],"highlightCaption":"Comparing Ges\xf9 e San Pietro in Friuli and in Sicilia side by side."},{"id":"2","title":"Cognitive Bias Ontology","description":"Ontology development for cognitive biases.","introText":"An ontology for a cluster of cognitive biases, part of a collective ontology of human biases built by the whole class of Knowledge Representation and Extraction (prof. Aldo Gangemi, University of Bologna, 2022/23).","gridImages":[{"src":"/images/projects/2-g1.jpg","caption":"The Cognitive Bias Codex and the clusters of biases our group developed."}],"middleText":"Our group, Marco Lamorte, Corrado Consiglio, Salvatore Di Marzo and I, modelled sixteen biases, from the gambler\'s fallacy and the hot hand fallacy to pareidolia, naive realism and the blind spot bias. Each went through the same eXtreme Design workflow: research and documentation, ideation and design, modelling and implementation, then presentation and visualisation. ChatGPT and Gemini were used early on for definitions, scenarios and user stories, and Framester among the resources for modelling.","highlightImage":"/images/projects/2-hl.jpg","conclusionText":"The process is documented in a public GitBook. It showed how much understanding of a domain an ontology needs before any modelling starts, and where language models help and where their answers had to be corrected.","imageSrc":"/images/projects/2.jpg","url":"https://the-bias-project.gitbook.io/cognitive-bias-ontologies-project-documentation","category":"Research","tags":["Ontology Engineering","Psychology"],"highlightCaption":"Introduction page of the project documentation."},{"id":"3","title":"wipEU","description":"Analyzing women\'s representation in the EU.","introText":"wipEU is an open data project on how the representation of women in positions of power and decision-making correlates across the European Union, and how it has changed over time.","gridImages":[{"src":"/images/projects/3-g1.jpg","caption":"Results: the share of women in the highest decision-making bodies of European institutions in 2023."},{"src":"/images/projects/3-g2.jpg","caption":"Choropleth map by country, position and year."},{"src":"/images/projects/3-g3.jpg","caption":"Line chart of women and men in European courts over time."},{"src":"/images/projects/3-g4.jpg","caption":"The source datasets, each with its provider, coverage and licence."}],"middleText":"We combined EIGE datasets across six areas (public administration, business and finance, politics, environment and climate change, education and research, law and institutions) into new mashup datasets, and assessed their quality, legal and ethical aspects as open data. The results can be explored by year from 2017 to 2023 in choropleth maps and line charts. In 2023, for example, women made up 20% of the highest decision-making bodies of European financial institutions and led 26.8% of major political parties.","highlightImage":"/images/projects/3-hl.jpg","conclusionText":"Final project for Open Access and Digital Ethics (2023/24, University of Bologna) with Salvatore Di Marzo and Matteo Guenci. I worked on the idea, data retrieval, the visualisations, the quality and legal analyses and the website, built with Leaflet and Plotly.js. The mashup datasets are released under CC BY 4.0.","imageSrc":"/images/projects/3.jpg","url":"https://alicepicco333.github.io/wipEU/","category":"Research","tags":["Data Visualization","Digital Ethics"],"highlightCaption":"Home page with the research question."},{"id":"5","title":"Glitching Materiality - @THEVOID","description":"Live performance using Hydra Video Synth.","introText":"A live coding performance with Karolis Lasys at Expanded Publishing Fest 2: Space-in / Space-out, organised by the Institute of Network Cultures in Amsterdam in 2024.","gridImages":[],"middleText":"The visuals were live-coded in Hydra Video Synth. The recording, about 18 minutes long, is published by the Institute of Network Cultures.","highlightImage":"/images/projects/5-hl.jpg","conclusionText":"","imageSrc":"/images/projects/5.jpg","url":"https://player.vimeo.com/video/980415428?loop=1&mute=1","category":"Live Coding","tags":["Live Coding","Performance"],"highlightCaption":"Still from the performance recording."},{"id":"6","title":"I Grandi Oggetti","description":"3D animated short inspired by The Big Lebowski.","introText":"A 3D animated short that retells the Coen brothers\' The Big Lebowski through its objects. It is conceived as a trailer, with the surreal atmosphere of David Lynch and the visual style of Wes Anderson.","gridImages":[],"middleText":"Made with Jessica Bugamelli and Laura Martorana as the final project of the 300-hour 3D Animation course run by Demetra Formazione with the Future Film Festival in 2023, co-funded by the European Social Fund+ and Regione Emilia-Romagna. The course covered 3D modelling and animation in Blender and Autodesk Maya.","highlightImage":"/images/projects/6-hl.jpg","conclusionText":"","imageSrc":"/images/projects/6.jpg","url":"https://www.youtube.com/watch?v=phYxE_Nl1hc&ab_channel=DemetraFormazione","category":"Past Projects","tags":["3D Modeling","3D Animation"],"highlightCaption":"Title card of the short."},{"id":"9","title":"Consider the Lobster","description":"Animated film contribution based on Foster Wallace’s essay.","introText":"An animated contribution to Quello che succede quando non riesco ad avere un\'idea veramente originale, a 2020 short by Davide di Lorenzo for Ababo Cinema about a young man trying to turn David Foster Wallace\'s essay on the Maine Lobster Festival into a film.","gridImages":[],"middleText":"","highlightImage":"/images/qks-highlight.jpg","conclusionText":"","imageSrc":"/images/projects/9.jpg","url":"https://www.youtube.com/watch?app=desktop&v=xYfUEoZoD64&ab_channel=AbaboCinema","category":"Past Projects","tags":["2D Animation"]},{"id":"10","title":"Collaboratory Creative Coding Jam","description":"Hydra live coding workshop and collective performance.","introText":"A Hydra Video Synth workshop I proposed and led in the HDSC2024 open programme of Hackers & Designers, at Het Wilde Weg in Amsterdam on 20 July 2024.","gridImages":[{"src":"/images/projects/10-g1.jpg","caption":"The workshop page on the Hackers & Designers site."}],"middleText":"Hydra is an open-source, browser-based live coding tool by Olivia Jack, inspired by modular synths. After an introduction to its primitives, textures and commands, up to fifteen participants made visuals from scratch, remixed video and live streams, and closed the afternoon with a collective live jam.","highlightImage":"/images/projects/10.jpg","conclusionText":"","imageSrc":"/images/projects/10.jpg","url":"https://hackersanddesigners.nl/collaboratory-creative-coding-jam.html","category":"Live Coding","tags":["Workshop Facilitation","Live Coding"]},{"id":"11","title":"Teigetje & Woelrat","description":"Collection website for the Amsterdam fashion label Teigetje & Woelrat, designed in Figma and built for the web.","introText":"A collection website for Teigetje & Woelrat, an Amsterdam label working across fashion, design and interior art. I designed it in Figma and built it as a React site.","gridImages":[{"src":"/images/projects/11-g1.jpg","caption":"The end of the hero and the footer with the studio\'s details."}],"middleText":"The site brings together a gallery of the current collection, an archive of past pieces, the label\'s history and a contact page, in English and Dutch.","highlightImage":"/images/projects/11-hl.jpg","conclusionText":"Built with React, TypeScript and Vite from the Figma design.","imageSrc":"/images/projects/11.jpg","url":"","category":"Design","tags":["UX Design","Web Development"],"highlightCaption":"Home page."},{"id":"12","title":"The Meme Ontology","description":"MEMO: an OWL ontology of internet memes, built from scraped meme data, linked to Wikidata and queryable with SPARQL.","introText":"MEMO is an ontology of internet memes, from my master\'s research Towards an Ontology of Memes (supervisor Fabio Vitali), which I began as a research intern at the Institute of Network Cultures in Amsterdam.","gridImages":[{"src":"/images/projects/12-g1.jpg","caption":"Temporal distribution of memes by format."},{"src":"/images/projects/12-g2.jpg","caption":"Platform of origin over time."},{"src":"/images/projects/12-g3.jpg","caption":"Creative productivity against cultural prominence."},{"src":"/images/projects/12-g4.jpg","caption":"Variant gallery: the dimensions along which a meme is transformed."},{"src":"/images/projects/12-g5.jpg","caption":"SPARQL explorer with example queries."}],"middleText":"Following Lev Manovich\'s cultural analytics, it treats memes as a large dataset rather than isolated texts. Around 5,000 images and their metadata, scraped from Know Your Meme, are described in an OWL ontology informed by FRBR across three areas: visual content, cultural references and format. CLIP is used to classify them semi-automatically.","highlightImage":"/images/projects/12-hl.jpg","conclusionText":"The ontology is published with LODE documentation, interactive visualisations of formats, platforms, periods and variants, and a SPARQL explorer with example queries, including links to Wikidata for regions and platforms.","imageSrc":"/images/projects/12.jpg","url":"","category":"Research","tags":["Ontology Engineering","Semantic Web"],"highlightCaption":"Home page: a wall of memes from the dataset."},{"id":"13","title":"Archivio Fondazione Luki Massa","description":"Digitisation of the Luki Massa Foundation archive, cataloguing its series with a shared file nomenclature and inventory.","introText":"Digitisation of the archive of Luki Massa, which documents lesbian and feminist activism from 1976 to 2015 and was inventoried by Emanuela Fiorletta in 2023.","gridImages":[],"middleText":"The work covers five of the archive\'s series: political groups, lesbian and feminist conferences, seminars and demonstrations, other lesbian, feminist and LGBTQI+ groups, the lesbian and feminist press, and Luki Massa\'s own notes and writings. Every scan follows a shared nomenclature (archive, series, subseries, file, documentary unit, page), and spreadsheets record the title, date, medium, material and a short description of each unit.","highlightImage":"","conclusionText":"","imageSrc":"","url":"","category":"Work in Progress","tags":["Digital Archives","Digitisation"]},{"id":"14","title":"5PIC3 live at Fullfillment Music Center","description":"Live-coded, audio-reactive visuals in Hydra at Fullfillment Music Center.","introText":"An audio-reactive visual set performed live as 5PIC3 at Fullfillment Music Center, written in Hydra Video Synth in real time.","gridImages":[{"src":"/images/projects/14-g1.jpg","caption":"The set opens with the code alone on the wall."},{"src":"/images/projects/14-g2.jpg","caption":"Noise textures in green."},{"src":"/images/projects/14-g3.jpg","caption":"Scanline glitches over the code."},{"src":"/images/projects/14-g4.jpg","caption":"Stretched colour bands near the end of the set."}],"middleText":"As is usual in live coding, the code was projected together with the visuals, so the room could watch the patches being typed, changed and broken as the music moved.","highlightImage":"/images/projects/14-hl.jpg","conclusionText":"","imageSrc":"/images/projects/14.jpg","url":"","category":"Live Coding","tags":["Live Coding","Hydra","Performance"],"highlightCaption":"The projection across the wall of the venue."},{"id":"15","title":"Culture4All","description":"Information visualization of access to culture across Italian regions, built on ISTAT and dati.cultura open data, with Corrado Consiglio and Salvatore Di Marzo.","introText":"Culture for All maps access to culture across Italy: where libraries, archives and museums are, how people use libraries, and how reading habits differ from region to region.","gridImages":[{"src":"/images/projects/15-g1.jpg","caption":"Libraries by province, 2022."},{"src":"/images/projects/15-g2.jpg","caption":"Library holdings by region and year."},{"src":"/images/projects/15-g3.jpg","caption":"Libraries, archives and museums on a pin map."},{"src":"/images/projects/15-g4.jpg","caption":"Library loans by category, grouped by region."},{"src":"/images/projects/15-g5.jpg","caption":"Reading habits by region, 2021."},{"src":"/images/projects/15-g6.jpg","caption":"Key findings."}],"middleText":"Built on open data from ISTAT, dati.cultura and cultural institutions, the site has five interactive visualisations: a choropleth map of libraries by province, a pie chart of library holdings, a pin map of libraries, archives and museums, library loans grouped by region, area, population or urban classification, and reading habits by region.","highlightImage":"/images/projects/15-hl.jpg","conclusionText":"Institutions cluster in Lombardy, Veneto, Tuscany and Lazio, cities borrow more than rural areas, and reading habits vary widely, which points to where cultural infrastructure needs investment. Made for Information Visualization (2023/24, University of Bologna) with Corrado Consiglio and Salvatore Di Marzo, who gathered and cleaned the data. I designed the visualisations and built the site with Leaflet, D3.js and Chart.js.","imageSrc":"/images/projects/15.jpg","url":"https://alicepicco333.github.io/culture4all/","category":"Past Projects","tags":["Data Visualization","Web Development"],"highlightCaption":"Home page."},{"id":"16","title":"Mary Shelley HTR","description":"Handwritten text recognition campaign with Transkribus: models trained on about 70 manuscript pages of Mary Shelley\'s Frankenstein and Mathilda.","introText":"A handwritten text recognition campaign on Mary Shelley\'s manuscripts: we trained Transkribus models to transcribe her handwriting automatically, to help the Shelley-Godwin Archive add new material faster.","gridImages":[{"src":"/images/projects/16-g1.jpg","caption":"Workflow: a manuscript page of Frankenstein and how the training set was built."},{"src":"/images/projects/16-g2.jpg","caption":"Learning curves: character error rate of the two models over the epochs."},{"src":"/images/projects/16-g3.jpg","caption":"Testing both models on an unseen page of Mathilda."}],"middleText":"The training set was 64 pages written only by Shelley, 36 from chapters 5 to 7 of Frankenstein and 28 from Mathilda, with the archive\'s transcriptions as ground truth and Transkribus\' Universal Lines model for the layout. We trained two models, one fine-tuned from the English M4 model and one from scratch, with a batch size of 10 over 100 epochs.","highlightImage":"/images/projects/16-hl.jpg","conclusionText":"On an unseen page of Mathilda the fine-tuned model was clearly more accurate. The ruler visible in the scans was read as text, which cropping would fix, and a three-day queue on Transkribus\' free tier left no time to recalibrate. Final project for Semantic Digital Libraries (University of Bologna, 2024) with Gaia Ortona and Chiara Parravicini. I worked on model training and built the website.","imageSrc":"/images/projects/16.jpg","url":"https://maryshelleyhtr-alicepicco333s-projects.vercel.app","category":"Past Projects","tags":["HTR","Digital Libraries"],"highlightCaption":"Project website."},{"id":"17","title":"Rijksmuseum Conversational AI Interface","description":"A conversational AI interface for the Rijksmuseum.","introText":"A conversational interface that helps visitors learn about and engage with the Rijksmuseum collection inside the museum. It is the Data Systems Project of the MSc Information Studies (2026/27), with Q42 and Curamando as stakeholders.","gridImages":[],"middleText":"The brief asks what a visitor needs for a rich experience in the galleries and which interface attributes contribute to it, from input and output modalities to visual widgets and the context a conversation sits in, and how that experience can be measured.","highlightImage":"","conclusionText":"","imageSrc":"","url":"","category":"Work in Progress","tags":["Conversational AI","Interaction Design"]},{"id":"18","title":"The Excavation Suit","description":"A speculative multimodal suit for colonists on Proxima Centauri b who reopen the nuclear waste sites their ancestors buried.","introText":"The Excavation Suit is a speculative wearable for a Multimodal Interaction Design course: a suit for the descendants of a colony on Proxima Centauri b, who reopen the nuclear waste sites their ancestors sealed.","gridImages":[],"middleText":"Radio fails under the star\'s flares, so gesture is a primary input, and every hazard registers across at least two of touch, vision and sound. This follows the Sandia recommendation that nuclear warnings be layered across several channels, and the \\"ray cat\\" idea of a warning that needs no literacy. Before leaving, the wearer marks the site for the next crew.","highlightImage":"","conclusionText":"The midterm prototype is an Arduino glove and forearm rig for the haptic and gesture loops, with a helmet-mounted colour sensor and an OLED display.","imageSrc":"","url":"","category":"Work in Progress","tags":["Speculative Design"]},{"id":"19","title":"OULAD Critical Dataset Analysis","description":"A living critical notebook on the Open University Learning Analytics Dataset (OULAD).","introText":"A living critical notebook for HCI Theory and Data that follows one dataset for eight weeks: the Open University Learning Analytics Dataset (OULAD).","gridImages":[],"middleText":"Each week adds a short entry and nothing is deleted: superseded decisions stay visible, with a change log and a log of AI use. It begins with a positionality note and asks what the dataset\'s categories capture and leave out about the students in it.","highlightImage":"","conclusionText":"","imageSrc":"","url":"","category":"Work in Progress","tags":["Critical Data Studies","HCI"]},{"id":"20","title":"Unobravo Redesign","description":"A research-led redesign of Unobravo\'s website and app, the Italian online therapy platform, to make the service easier to understand and trust.","introText":"Unobravo connects people with therapists over video call. Its website tried to be a marketing page, a guide and an onboarding flow at once, and the app offered no explanation of the service at all. I redesigned both, from interviews to a tested Figma prototype.","gridImages":["/images/projects/20-a.jpg","/images/projects/20-b.jpg","/images/projects/20-c.jpg","/images/projects/20-d.jpg"],"middleText":"The research combined interviews across three age groups, a competitor study of Serenis, expert reviews and think-aloud testing. It surfaced nine usability issues: an overwhelming \\"how it works\\" page, calls to action that pushed people into the questionnaire before they understood the service, opaque therapist matching, scheduling that ignored stated preferences, a full test to repeat just to change therapist, no way to compare profiles, hidden pricing and privacy information, and an app whose navigation was buried in a sidebar.","highlightImage":"/images/projects/unobravo/hero.jpg","conclusionText":"Over three iterations the design added a calmer home page, a real dashboard with the next appointment and pricing, three therapist proposals with a \\"why you match\\" explanation, filters to compare profiles, and a way to change therapist by only updating preferences. In the summative test of the final version, all four participants completed every task with no errors, and the average SUS score rose from 75 on the original product to 91.25.","imageSrc":"/images/projects/20.jpg","url":"","category":"Design","tags":["UX Design","HCI","Interaction Design","Figma"],"caseStudy":{"stats":[{"value":"91.25","label":"SUS score on the final version, up from 75 on the original product"},{"value":"100%","label":"task completion in the summative test, with zero errors"},{"value":"9","label":"usability issues found in research, all resolved"},{"value":"83","label":"screens in the final interactive prototype"}],"overview":[{"label":"Role","value":"Solo project: research, UX and UI design, prototyping, testing"},{"label":"Context","value":"HCI course project, Digital Humanities and Digital Knowledge, University of Bologna"},{"label":"Timeline","value":"Research autumn 2025 \xb7 ver0 Jan 2026 \xb7 final version Mar 2026"},{"label":"Methods","value":"Segmentation, interviews, expert review, think-aloud testing, SUS, persona, blueprint, IA"},{"label":"Tools","value":"Figma (design system, prototyping, motion), Excel for test analysis"}],"context":{"text":"Unobravo is a leading European online psychology service, founded in Italy in 2019, that matches people with licensed therapists over video call. Many potential users hesitate: they worry about privacy, doubt that online therapy can feel human, and don\'t understand how the matching works. The goal was to reduce that reluctance and make the service easy to understand and trust, across ages and levels of digital literacy.","goals":[{"title":"Transparency","text":"Explain data practices, pricing and the matching process clearly, so privacy concerns can be resolved rather than hidden in a footer."},{"title":"Personalisation","text":"Adapt the journey to different needs and levels of readiness, from someone just exploring to someone ready to book."}]},"methods":[{"meta":"Age \xd7 readiness to change","title":"Segmentation","text":"Three age groups (25–34, 35–44, 45–55) crossed with the Stages of Change model. The focus segment: young adults in the Preparation stage."},{"meta":"8 interviews \xb7 3 age groups","title":"Interviews and market research","text":"Four young adults, two mid-career and two mature adults, plus published data on Gen Z mental health, stigma and access to support."},{"meta":"Unobravo vs Serenis","title":"Expert review","text":"Direct and reverse checkpoint reviews of Unobravo and its competitor Serenis, on website and app."},{"meta":"3 + 3 sessions \xb7 think-aloud","title":"Preliminary testing","text":"Four tasks on each product: understand the service, take the matching test, change therapist, compare profiles. SUS on the original: 75."},{"meta":"Blueprint \xb7 IA","title":"Service blueprint and information architecture","text":"Mapped the current and proposed journeys for the website and app, then restructured the IA to separate explanation from conversion."},{"meta":"Protagonist + 6 cast","title":"Personas","text":"A protagonist persona and a supporting cast of six, used to test decisions against different ages, needs and attitudes to therapy."}],"persona":{"segment":"Young adult (25–34) \xb7 Preparation","name":"Luca Taglioni","facts":"29 \xb7 graphic designer in Milan \xb7 high digital proficiency \xb7 anxiety, panic attacks, sleep difficulties","quote":"There is hope, even when your brain tells you there isn\'t.","story":"Friends in therapy have encouraged Luca to start, and he feels ready. He expects polished, personal digital products and dislikes rigid, bureaucratic flows. He will invest time and money, but only if the platform feels trustworthy and human.","needs":["A clean, professional interface that still feels warm, not clinical","Filters and recommendations tailored to anxiety and sleep issues","A frictionless booking flow with availability, cost and policies up front","Reassuring, empathetic microcopy for a first-time therapy user"]},"issues":[{"id":"I01","title":"Overwhelming and unclear “How it works” experience","impact":5,"persistence":5,"evidence":"No tested user could explain how Unobravo works. “Oh my god, there is so much stuff here.”"},{"id":"I02","title":"Calls to action push people into the questionnaire too early","impact":5,"persistence":4,"evidence":"Users clicked “Trova il tuo Unobravo” expecting an explanation, and landed in the test."},{"id":"I03","title":"Matching logic is opaque","impact":5,"persistence":4,"evidence":"The promised three profiles were not delivered, and users were forced to retake the test."},{"id":"I04","title":"Scheduling ignores stated preferences","impact":5,"persistence":4,"evidence":"A morning preference was ignored, with no explanation when slots were unavailable."},{"id":"I05","title":"Changing therapist means retaking the whole test","impact":4,"persistence":4,"evidence":"Users repeated the full questionnaire just to change availability."},{"id":"I06","title":"No way to compare therapists","impact":4,"persistence":4,"evidence":"The “compare profiles” task failed for every user; the index was missing from the app."},{"id":"I07","title":"Pricing and privacy are hard to find","impact":4,"persistence":3,"evidence":"Users searched the wrong sections and misremembered prices; privacy lived only in the footer."},{"id":"I08","title":"Weak navigation and no escape routes","impact":3,"persistence":4,"evidence":"Back options and orientation cues were missing along key flows."},{"id":"I09","title":"App navigation hidden in a sidebar","impact":3,"persistence":3,"evidence":"The app offered no explanation of the service and no dashboard for ongoing therapy."}],"urgency":[{"src":"/images/projects/unobravo/research/urgency-current.jpg","alt":"Urgency curve of the original product","caption":"Urgency curve, original product: impact against persistence"},{"src":"/images/projects/unobravo/research/urgency-ver1.jpg","alt":"Urgency curve after the first iteration","caption":"Urgency curve after ver1"}],"recommendations":[{"id":"R01","addresses":"I01, I02","title":"Separate explaining from converting","text":"A non-transactional “Scopri Unobravo” path explains the service, matching, costs and privacy before anyone is asked to start the test."},{"id":"R02","addresses":"I02","title":"Calmer calls to action","text":"“Scopri come funziona” sits next to “Inizia”, so users choose between exploring and committing."},{"id":"R03","addresses":"I03","title":"Make matching explicit","text":"Always three proposals, each with a “Why we chose this therapist for you” explanation."},{"id":"R04","addresses":"I04, I05","title":"Decouple preferences from matching","text":"Change schedule or preferences without retaking the full questionnaire."}],"iterations":[{"name":"Version 0","date":"11 January 2026","evaluation":"Informal action analysis","text":"First restructuring: an explanatory entry point, a pill-shaped tab bar instead of the sidebar, a dashboard."},{"name":"Version 1","date":"20 January 2026","evaluation":"Think-aloud test \xb7 SUS 91.67","text":"Added change and delete appointment, clearer therapy progress, and routes to the therapist profile."},{"name":"Version 2 \xb7 final","date":"8 March 2026","evaluation":"Summative test \xb7 SUS 91.25","text":"Three proposals with match explanations, filters to compare profiles, change therapist from the first screen, quick actions."}],"beforeAfter":[{"src":"/images/projects/unobravo/research/ba-onboarding.jpg","alt":"Before and after: Onboarding","caption":"Onboarding"},{"src":"/images/projects/unobravo/research/ba-test-question-example.jpg","alt":"Before and after: Questionnaire","caption":"Questionnaire"},{"src":"/images/projects/unobravo/research/ba-therapist-choice.jpg","alt":"Before and after: Therapist choice","caption":"Therapist choice"},{"src":"/images/projects/unobravo/research/ba-therapist-profile.jpg","alt":"Before and after: Therapist profile","caption":"Therapist profile"},{"src":"/images/projects/unobravo/research/ba-filtered-search.jpg","alt":"Before and after: Filtered search","caption":"Filtered search"},{"src":"/images/projects/unobravo/research/ba-pick-appointment.jpg","alt":"Before and after: Pick an appointment","caption":"Pick an appointment"},{"src":"/images/projects/unobravo/research/ba-calendar.jpg","alt":"Before and after: Calendar","caption":"Calendar"},{"src":"/images/projects/unobravo/research/ba-dashboard.jpg","alt":"Before and after: Dashboard","caption":"Dashboard"},{"src":"/images/projects/unobravo/research/ba-change-therapist.jpg","alt":"Before and after: Change therapist","caption":"Change therapist"},{"src":"/images/projects/unobravo/research/ba-homepage.jpg","alt":"Before and after: Homepage","caption":"Homepage"}],"flows":[{"src":"/images/projects/unobravo/flow-01-onboarding.jpg","alt":"Onboarding and discovery screens","caption":"01 \xb7 Onboarding and discovery: from first contact to an informed choice of path"},{"src":"/images/projects/unobravo/flow-02-questionnaire.jpg","alt":"Matching questionnaire screens","caption":"02 \xb7 Matching questionnaire: one question at a time, visible progress, support always at hand"},{"src":"/images/projects/unobravo/flow-03-portal.jpg","alt":"Professionals portal screens","caption":"03 \xb7 Professionals portal: browse, filter and compare profiles independently"},{"src":"/images/projects/unobravo/flow-04-booking.jpg","alt":"Proposals and booking screens","caption":"04 \xb7 Proposals and booking: three explained proposals, booking in two taps, clear payment"},{"src":"/images/projects/unobravo/flow-05-personal-area.jpg","alt":"Personal area screens","caption":"05 \xb7 Personal area: next appointment, chat, invoices and diary in one tab bar"},{"src":"/images/projects/unobravo/flow-06-online-session.jpg","alt":"Online session screens","caption":"06 \xb7 Online session: from device check to feedback without leaving the app"}],"motion":[{"src":"/images/projects/unobravo/motion-splash.mp4","poster":"/images/projects/unobravo/motion-splash-poster.jpg","caption":"Splash: portraits pop in one by one, then the message and actions rise"},{"src":"/images/projects/unobravo/motion-booked.mp4","poster":"/images/projects/unobravo/motion-booked-poster.jpg","caption":"Booking confirmed: the success mark settles with a soft overshoot"},{"src":"/images/projects/unobravo/motion-call.mp4","poster":"/images/projects/unobravo/motion-call-poster.jpg","caption":"Video session: controls slide in and the live indicator pulses"}],"prototype":{"text":"The full prototype is wired in Figma: about 200 connections across six flows, with interactive answer options, filter sheets and smart-animated questionnaire progress. Try it below, or open it in Figma to switch between flows.","embed":"https://embed.figma.com/proto/g15NKSEccuWdV7a2z9HCoI/Unobravo-Redesign?node-id=5-2&starting-point-node-id=5-2&scaling=scale-down&content-scaling=fixed&embed-host=share","url":"https://www.figma.com/proto/g15NKSEccuWdV7a2z9HCoI/Unobravo-Redesign?node-id=5-2&starting-point-node-id=5-2&scaling=scale-down&content-scaling=fixed","poster":"/images/projects/unobravo/hero.jpg"},"system":{"text":"Behind the screens is a small design system: 34 variables (10 primitives, 13 semantic colours, 7 spacing and 4 radius values), 14 text styles and 29 components. Every text colour passes WCAG AA contrast and every touch target is at least 44 px.","images":[{"src":"/images/projects/unobravo/system/colour.jpg","alt":"Colour tokens","caption":"Colour: primitives feed semantic tokens"},{"src":"/images/projects/unobravo/system/cards.jpg","alt":"Card components","caption":"Cards: option, price, therapist, appointment, calendar"},{"src":"/images/projects/unobravo/system/illustration.jpg","alt":"Illustration components","caption":"Illustrations for sections, success and support"}]},"results":{"text":"Four participants completed every task on the final version, working alone while recording their screen, with no errors. Scores also became more consistent as the design matured (variance fell from 58.33 to 29.69). Participants singled out the “why this therapist” explanation as what made the matching feel trustworthy.","sus":[{"label":"Original product","value":75},{"label":"Version 1","value":91.67},{"label":"Final version","value":91.25}],"tasks":[{"task":"Understand how the service works","time":"~1 min 32 s","success":"100%","errors":"0"},{"task":"Take the test and book","time":"~5 min","success":"100%","errors":"0"},{"task":"Change therapist for scheduling","time":"~25 s","success":"100%","errors":"0"},{"task":"Compare and change therapist","time":"~31 s","success":"100%","errors":"0"}]},"reflection":["The biggest change was structural, not visual: separating “understand the service” from “start the test” fixed three critical issues at once. For a mental-health service, trust comes from transparency: showing how matching works, what it costs and what happens to your data.","The final version adds what a real product would need next: crisis support and health-data consent in the questionnaire, empty and error states, and the online session itself. The samples were small (three to four people per round), so the next step would be a larger test across all age segments."]}}],"Fb":"I\'m Alice, an anthropologist and digital humanities expert based in Amsterdam, blending critical research with creative technologies across cultural analysis, web development, and interactive design.","resume":{"tagline":"Anthropology / Digital Humanities / Design","description":"I work at the intersection of culture, technology, and design, weaving together critical research and creative experimentation. With a background in cultural anthropology and a strong foundation in digital humanities, my projects range from interactive archives and feminist data visualizations to live-coded performances and augmented reality design. Whether I’m mapping digital territories, building ontologies of cognitive bias, or glitching visual narratives in real time, I’m driven by curiosity and a commitment to inclusive, ethical tech. I enjoy working across media and disciplines — from semantic web development to storytelling with code — always with a reflexive, research-oriented approach.","experiences":[{"id":"1","dates":"March 2024 - June 2024","type":"Full Time Internship","position":"Research and Development Intern at Institute of Network Cultures","bullets":"Practice-based research on digital cultures with cultural analytics and visualization methods"},{"id":"2","dates":"March 2024 - Present","type":"Funded Program","position":"Digital Maker at The Hmm, DEN","bullets":"Mapping cultural digital spaces for digital transformation in the Netherlands"},{"id":"3","dates":"September 2023 - January 2024","type":"Part Time","position":"Digital Literacy Educator at NINA","bullets":"Home visits to enhance elderly digital literacy"},{"id":"4","dates":"August 2023 - September 2023","type":"Freelance","position":"Digital Designer at MONINGA","bullets":"Created Instagram filter for Vitamina Festival using Blender and Meta Spark AR"},{"id":"5","dates":"May 2022 - October 2022","type":"Full Time","position":"Customer Service Agent at Concentrix","bullets":"Customer support and issue resolution on Meta social media platforms"}],"education":{"universityName":"International Master\'s Degree - Digital Humanities and Digital Knowledge at University of Bologna","universityDate":"2022-2025","universityPara":"Focus on UX and Web Dev, courses in Data Science, Semantic Web, Visualization, etc."},"education2":{"universityName":"Bachelor\'s Degree - Cultural Anthropology at University of Bologna","universityDate":"2018-2022","universityPara":"Thesis on queer Muslim youth through ethnography on social media"}}}')}}]);